function h(s){let x=2166136261>>>0;for(let i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,16777619)>>>0;}return x;}
const N=4,ROWS=12000;
function dist(keyFn){const c=[0,0,0,0];for(let i=0;i<ROWS;i++){c[h(keyFn(i))%N]++;}return c;}
// high cardinality: tenant_id
const byTenant=dist(i=>'t'+i);
// low cardinality: country, power-law (60% US, 20% DE, 13.33% IN, 6.66% BR)
function country(i){const m=i%15;if(m<9)return'US';if(m<12)return'DE';if(m<14)return'IN';return'BR';}
const byCountry=dist(i=>country(i));
const max=Math.max(...byCountry),min=Math.min(...byCountry);
console.log('tenant_id mod 4: '+byTenant.join(','));
console.log('country  mod 4: '+byCountry.join(','));
console.log('country skew (max/min): '+(max/min).toFixed(2));
